'',
'.mf-rate-card.mf-purple {',
'    background:',
'        linear-gradient(',
'            135deg,',
'            #f8f5ff 0%,',
'            #f4f0ff 100%',
'        );',
'}',
'',
'',
'/* =========================================================',
'   TOP PART',
'   ========================================================= */',
'',
'.mf-rate-top {',
'    display: grid;',
'',
'    grid-template-columns:',
'        62px',
'        minmax(0, 1fr)',
'        24px;',
'',
'    align-items: start;',
'',
'    column-gap: 14px;',
'}',
'',
'',
'/* =========================================================',
'   ICON BOX',
'   ========================================================= */',
'',
'.mf-rate-icon {',
'    width: 62px;',
'    height: 60px;',
'',
'    border-radius: 12px;',
'',
'    display: flex;',
'    align-items: center;',
'    justify-content: center;',
'',
'    font-size: 30px;',
'}',
'',
'',
'/* Blue */',
'',
'.mf-blue .mf-rate-icon {',
'    background: #dfedff;',
'    color: #075de8;',
'}',
'',
'',
'/* Green */',
'',
'.mf-green .mf-rate-icon {',
'    background: #ddf7e7;',
'    color: #169238;',
'}',
'',
'',
'/* Purple */',
'',
'.mf-purple .mf-rate-icon {',
'    background: #e9e1ff;',
'    color: #5a31dc;',
'}',
'',
'',
'/* =========================================================',
'   PRODUCT NAME',
'   ========================================================= */',
'',
'.mf-product-name {',
'    color: #0a1f44;',
'',
'    font-size: 16px;',
'    font-weight: 600;',
'',
'    line-height: 1.2;',
'',
'    margin-top: 5px;',
'}',
'',
'',
'/* =========================================================',
'   RATE',
'   ========================================================= */',
'',
'.mf-interest-rate {',
'    color: #071d46;',
'',
'    font-size: 30px;',
'    font-weight: 800;',
'',
'    line-height: 1;',
'',
'    letter-spacing: -0.7px;',
'',
'    margin-top: 7px;',
'}',
'',
'',
'/* =========================================================',
'   ARROW',
'   ========================================================= */',
'',
'.mf-rate-arrow {',
'    font-size: 24px;',
'',
'    line-height: 1;',
'',
'    margin-top: 14px;',
'',
'    text-align: right;',
'}',
'',
'',
'.mf-arrow-blue {',
'    color: #075de8;',
'}',
'',
'',
'.mf-arrow-green {',
'    color: #138b32;',
'}',
'',
'',
'.mf-arrow-purple {',
'    color: #5423d9;',
'}',
'',
'',
'/* =========================================================',
'   DETAILS',
'   ========================================================= */',
'',
'.mf-rate-details {',
'    display: grid;',
'',
'    grid-template-columns:',
'        0.9fr',
'        1.15fr',
'        1.15fr;',
'',
'    column-gap: 20px;',
'',
'    margin-top: 19px;',
'',
'    padding-left: 10px;',
'}',
'',
'',
'/* Label */',
'',
'.mf-detail-label {',
'    color: #66728b;',
'',
'    font-size: 12px;',
'    font-weight: 400;',
'',
'    line-height: 1.2;',
'',
'    white-space: nowrap;',
'}',
'',
'',
'/* Value */',
'',
'.mf-detail-value {',
'    color: #17284c;',
'',
'    font-size: 14px;',
'    font-weight: 600;',
'',
'    margin-top: 6px;',
'',
'    line-height: 1.2;',
'}',
'',
'',
'/* =========================================================',
'   RESPONSIVE',
'   ========================================================= */',
'',
'@media (max-width: 900px) {',
'',
'    #mortgage-rate-cards .a-CardView-items {',
'        grid-template-columns:',
'            repeat(2, minmax(0, 1fr)) !important;',
'    }',
'',
'}',
'',
'',
'@media (max-width: 650px) {',
'',
'    #mortgage-rate-cards .a-CardView-items {',
'        grid-template-columns:',
'            1fr !important;',
'    }',
'',
'    .mf-rate-details {',
'        grid-template-columns:',
'            repeat(3, minmax(0, 1fr));',
'',
'        column-gap: 10px;',
'    }',
'',
'}',
'',
'',
'@media (max-width: 430px) {',
'',
'    .mf-rate-details {',
'        grid-template-columns: 1fr;',
'        row-gap: 13px;',
'    }',
'',
'}'))
