'function(options) {',
'',
'    options.orientation = "vertical";',
'',
'    options.dataFilter = function(data) {',
'',
'        var colors = [',
'            "#5B9CF6",  // Draft',
'            "#FFC845",  // Submitted',
'            "#66C56C",  // Under Review',
'            "#4A86F7",  // Approved',
'            "#F45757"   // Rejected',
'        ];',
'',
'        if (',
'            data.series &&',
'            data.series.length > 0 &&',
'            data.series[0].items',
'        ) {',
'',
'            data.series[0].items.forEach(function(item, index) {',
'',
'                if (colors[index]) {',
'                    item.color = colors[index];',
'                }',
'',
'            });',
'',
'        }',
'',
'        return data;',
'    };',
'',
'    return options;',
'}'))
