wwv_flow_imp_page.create_page(
 p_id=>2
,p_name=>'Mortgage Calculator'
,p_alias=>'MORTGAGE-CALCULATOR'
,p_step_title=>'Mortgage Calculator'
,p_autocomplete_on_off=>'OFF'
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* =========================================================',
'   MORTGAGE CALCULATOR',
'   ========================================================= */',
'',
':root {',
'    --mf-navy: #08174a;',
'    --mf-blue: #176ff2;',
'    --mf-text: #526487;',
'    --mf-border: #dce5f0;',
'    --mf-soft: #f7f9fc;',
'    --mf-green: #b8e313;',
'}',
'',
'',
'/* =========================================================',
'   REGION BASE',
'   ========================================================= */',
'',
'.mf-calc-panel,',
'.mf-results-panel,',
'.mf-amortization-panel,',
'.mf-how-panel {',
'    width: 100%;',
'    max-width: 100%;',
'    min-width: 0;',
'',
'    box-sizing: border-box;',
'',
'    background: #ffffff;',
'',
'    border: 1px solid var(--mf-border);',
'    border-radius: 14px;',
'',
'    box-shadow: 0 3px 14px rgba(8, 23, 74, 0.05);',
'',
'    overflow: hidden;',
'}',
'',
'',
'/* =========================================================',
'   REGION HEADERS',
'   ========================================================= */',
'',
'.mf-calc-panel .t-Region-header,',
'.mf-results-panel .t-Region-header,',
'.mf-amortization-panel .t-Region-header,',
'.mf-how-panel .t-Region-header {',
'    padding: 16px 18px 6px;',
'',
'    background: transparent;',
'',
'    border: 0;',
'}',
'',
'',
'.mf-calc-panel .t-Region-title,',
'.mf-results-panel .t-Region-title,',
'.mf-amortization-panel .t-Region-title,',
'.mf-how-panel .t-Region-title {',
'    color: var(--mf-navy);',
'',
'    font-size: 18px;',
'    font-weight: 800;',
'}',
'',
'',
'/* =========================================================',
'   REGION BODY',
'   ========================================================= */',
'',
'.mf-calc-panel .t-Region-body,',
'.mf-results-panel .t-Region-body,',
'.mf-amortization-panel .t-Region-body,',
'.mf-how-panel .t-Region-body {',
'    padding: 10px 18px 16px !important;',
'',
'    box-sizing: border-box;',
'',
'    width: 100%;',
'    max-width: 100%;',
'    min-width: 0;',
'}',
'',
'',
'/* =========================================================',
'   INPUT + RESULTS SAME HEIGHT',
'   ========================================================= */',
'',
'#calculator-inputs,',
'#calculation-results {',
'    width: 100%;',
'    max-width: 100%;',
'',
'    min-height: 410px;',
'    height: auto;',
'',
'    box-sizing: border-box;',
'}',
'',
'',
'/* Prevent overflow */',
'',
'#calculator-inputs *,',
'#calculation-results * {',
'    box-sizing: border-box;',
'}',
'',
'',
'#calculator-inputs .t-Region-bodyWrap,',
'#calculation-results .t-Region-bodyWrap,',
'#calculator-inputs .t-Region-body,',
'#calculation-results .t-Region-body {',
'    width: 100%;',
'    max-width: 100%;',
'    min-width: 0;',
'',
'    overflow: hidden;',
'}',
'',
'',
'/* =========================================================',
'   CALCULATOR INPUTS',
'   ========================================================= */',
'',
'#calculator-inputs .t-Form-fieldContainer {',
'    margin-bottom: 10px;',
'}',
'',
'',
'#calculator-inputs .t-Form-label {',
'    color: var(--mf-navy);',
'',
'    font-size: 14px;',
'    font-weight: 700;',
'',
'    margin-bottom: 4px;',
'}',
'',
'',
'/* Input fields */',
'',
'#calculator-inputs input.apex-item-text,',
'#calculator-inputs select.apex-item-select {',
'    width: 100%;',
'    max-width: 100%;',
'',
'    min-height: 40px;',
'',
'    padding: 7px 12px;',
'',
'    border: 1px solid #ccd8e8 !important;',
'    border-radius: 8px !important;',
'',
'    background: #ffffff;',
'',
'    color: var(--mf-navy);',
'',
'    font-size: 14px;',
'',
'    box-shadow: none;',
'',
'    transition:',
'        border-color 0.15s ease,',
'        box-shadow 0.15s ease;',
'}',
'',
'',
'/* Input focus */',
'',
'#calculator-inputs input.apex-item-text:focus,',
'#calculator-inputs select.apex-item-select:focus {',
'    border-color: var(--mf-blue) !important;',
'',
'    box-shadow:',
'        0 0 0 3px rgba(23, 111, 242, 0.10);',
'}',
'',
'',
'/* =========================================================',
'   INTEREST RATE + TERM',
'   ========================================================= */',
'',
'#P2_INTEREST_RATE_CONTAINER,',
'#P2_LOAN_TERM_CONTAINER {',
'    padding: 9px 12px !important;',
'',
'    background: var(--mf-soft);',
'',
'    border: 1px solid #e2e8f1;',
'    border-radius: 8px;',
'',
'    margin-bottom: 8px !important;',
'}',
'',
'',
'#P2_INTEREST_RATE_CONTAINER .apex-item-display-only,',
'#P2_LOAN_TERM_CONTAINER .apex-item-display-only {',
'    display: block;',
'',
'    margin-top: 3px;',
'',
'    padding: 0 !important;',
'',
'    border: 0 !important;',
'',
'    background: transparent !important;',
'',
'    color: var(--mf-navy);',
'',
'    font-size: 16px;',
'    font-weight: 800;',
'}',
'',
'',
'/* =========================================================',
'   CALCULATE BUTTON',
'   ========================================================= */',
'',
'.mf-btn-calculate {',
'    min-height: 39px;',
'',
'    padding: 0 18px !important;',
'',
'    background: var(--mf-blue) !important;',
'',
'    border: 1px solid var(--mf-blue) !important;',
'    border-radius: 8px !important;',
'',
'    color: #ffffff !important;',
'',
'    font-weight: 700;',
'}',
'',
'',
'.mf-btn-calculate:hover {',
'    background: #0e5fd5 !important;',
'    border-color: #0e5fd5 !important;',
'}',
'',
'',
'/* =========================================================',
'   CALCULATION RESULTS',
'   ========================================================= */',
'',
'#P2_LOAN_AMOUNT_CONTAINER,',
'#P2_MONTHLY_PAYMENT_CONTAINER,',
'#P2_LTV_CONTAINER,',
'#P2_DTI_CONTAINER,',
'#P2_RISK_LEVEL_CONTAINER {',
'    width: 100%;',
'    max-width: 100%;',
'',
'    min-height: 58px;',
'',
'    margin: 0 0 8px !important;',
'',
'    padding: 9px 12px !important;',
'',
'    background: var(--mf-soft);',
'',
'    border: 1px solid #e1e8f2;',
'    border-radius: 8px;',
'}',
'',
'',
'/* Result labels */',
'',
'#calculation-results .t-Form-label {',
'    color: #607096;',
'',
'    font-size: 12px;',
'    font-weight: 700;',
'',
'    line-height: 1.2;',
'}',
'',
'',
'/* Result values */',
'',
'#calculation-results .apex-item-display-only {',
'    display: block;',
'',
'    width: 100%;',
'    max-width: 100%;',
'',
'    margin-top: 3px;',
'',
'    padding: 0 !important;',
'',
'    border: 0 !important;',
'',
'    background: transparent !important;',
'',
'    color: var(--mf-navy);',
'',
'    font-size: 19px;',
'    font-weight: 800;',
'',
'    line-height: 1.15;',
'',
'    overflow-wrap: anywhere;',
'}',
'',
'',
'/* =========================================================',
'   RISK LEVEL',
'   ========================================================= */',
'',
'#P2_RISK_LEVEL_CONTAINER .apex-item-display-only {',
'    display: inline-block;',
'',
'    width: auto;',
'',
'    margin-top: 5px;',
'',
'    padding: 5px 11px !important;',
'',
'    border-radius: 20px;',
'',
'    background: #fee9e7 !important;',
'',
'    color: #b42318 !important;',
'',
'    font-size: 13px;',
'    font-weight: 800;',
'}',
'',
'',
'/* =========================================================',
'   APPLY BUTTON',
'   ========================================================= */',
'',
'.mf-btn-apply {',
'    min-height: 39px;',
'',
'    padding: 0 18px !important;',
'',
'    background: var(--mf-green) !important;',
'',
'    border: 1px solid #a8d500 !important;',
'    border-radius: 8px !important;',
'',
'    color: #172000 !important;',
'',
'    font-weight: 800;',
'}',
'',
'',
'.mf-btn-apply:hover {',
'    background: #a8d600 !important;',
'}',
'',
'',
'/* =========================================================',
'   AMORTIZATION REGION',
'   ========================================================= */',
'',
'.mf-amortization-panel .t-Report-report {',
'    width: 100%;',
'}',
'',
'',
'.mf-amortization-panel .t-Report-colHead {',
'    padding: 10px 12px;',
'',
'    background: #f3f6fa;',
'',
'    color: var(--mf-navy);',
'',
'    font-size: 13px;',
'    font-weight: 700;',
'',
'    border-bottom: 1px solid var(--mf-border);',
'}',
'',
'',
'.mf-amortization-panel .t-Report-cell {',
'    padding: 9px 12px;',
'',
'    color: var(--mf-text);',
'',
'    font-size: 13px;',
'',
'    border-bottom: 1px solid #edf1f6;',
'}',
'',
'',
'/* =========================================================',
'   HOW CALCULATIONS WORK',
'   ========================================================= */',
'',
'.mf-how-list {',
'    display: flex;',
'',
'    flex-direction: column;',
'',
'    gap: 18px;',
'}',
'',
'',
'.mf-how-row {',
'    display: flex;',
'',
'    align-items: flex-start;',
'',
'    gap: 14px;',
'}',
'',
'',
'/* Number circles */',
'',
'.mf-how-number {',
'    width: 32px;',
'    height: 32px;',
'',
'    min-width: 32px;',
'',
'    display: flex;',
'',
'    align-items: center;',
'    justify-content: center;',
'',
'    border-radius: 50%;',
'',
'    background: #eef8cf;',
'',
'    color: #263600;',
'',
'    font-size: 14px;',
'    font-weight: 800;',
'}',
'',
'',
'/* Text */',
'',
'.mf-how-content {',
'    padding-top: 1px;',
'}',
'',
'',
'.mf-how-title {',
'    margin-bottom: 4px;',
'',
'    color: var(--mf-navy);',
'',
'    font-size: 16px;',
'    font-weight: 800;',
'',
'    line-height: 1.3;',
'}',
'',
'',
'.mf-how-description {',
'    color: #68799e;',
'',
'    font-size: 14px;',
'',
'    line-height: 1.55;',
'}',
'',
'',
'/* Lightbulb icon */',
'',
'.mf-how-panel .t-Region-title .fa {',
'    margin-right: 8px;',
'',
'    color: #91b814;',
'}',
'',
'',
'/* =========================================================',
'   EQUAL HEIGHT COLUMNS',
