wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(2135294794225916024)
,p_plug_name=>'Amortization Preview'
,p_static_id=>'amortization-preview'
,p_region_css_classes=>'mf-amortization-panel'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4075786578761660127
,p_plug_display_sequence=>60
,p_plug_grid_column_span=>8
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with params as (',
'    select',
'        to_number(:P2_LOAN_AMOUNT)',
'            as loan_amount,',
'',
'        to_number(:P2_MONTHLY_PAYMENT)',
'            as monthly_payment,',
'',
'        (',
'            to_number(:P2_INTEREST_RATE)',
'            / 100',
'            / 12',
'        ) as monthly_rate',
'',
'    from dual',
'),',
'',
'payment_numbers as (',
'    select level as payment_no',
'    from dual',
'    connect by level <= 6',
'),',
'',
'balances as (',
'    select',
'        n.payment_no,',
'        p.loan_amount,',
'        p.monthly_payment,',
'        p.monthly_rate,',
'',
'        case',
'',
'            when p.monthly_rate = 0 then',
'                greatest(',
'                    p.loan_amount',
'                    -',
'                    (',
'                        p.monthly_payment',
'                        * (n.payment_no - 1)',
'                    ),',
'                    0',
'                )',
'',
'            else',
'',
'                p.loan_amount',
'                *',
'                power(',
'                    1 + p.monthly_rate,',
'                    n.payment_no - 1',
'                )',
'',
'                -',
'',
'                p.monthly_payment',
'                *',
'                (',
'                    (',
'                        power(',
'                            1 + p.monthly_rate,',
'                            n.payment_no - 1',
'                        )',
'                        - 1',
'                    )',
'                    /',
'                    p.monthly_rate',
'                )',
'',
'        end as previous_balance',
'',
'    from params p',
'    cross join payment_numbers n',
'),',
'',
'amounts as (',
'    select',
'        payment_no,',
'        monthly_payment,',
'        monthly_rate,',
'        previous_balance,',
'',
'        case',
'            when monthly_rate = 0',
'                then 0',
'            else',
'                previous_balance',
'                * monthly_rate',
'        end as interest_amount',
'',
'    from balances',
')',
'',
'select',
'    payment_no as payment_number,',
'',
'    add_months(',
'        trunc(sysdate, ''MM''),',
'        payment_no',
'    ) as payment_date,',
'',
'    round(',
'        least(',
'            monthly_payment - interest_amount,',
'            previous_balance',
'        ),',
'        2',
'    ) as principal,',
'',
'    round(',
'        interest_amount,',
'        2',
'    ) as interest,',
'',
'    round(',
'        greatest(',
'            previous_balance',
'            -',
'            least(',
'                monthly_payment - interest_amount,',
'                previous_balance',
'            ),',
'            0',
'        ),',
'        2',
'    ) as balance',
'',
'from amounts',
'',
'where :P2_LOAN_AMOUNT is not null',
'',
'order by payment_no'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
