    '',
    '        apex.server.process(',
    '            "CREATE_MORTGAGE_DRAFT",',
    '            {',
    '                pageItems:',
    '                    "#P2_LOAN_PRODUCT_ID," +',
    '                    "#P2_ANNUAL_INCOME," +',
    '                    "#P2_MONTHLY_DEBT," +',
    '                    "#P2_PROPERTY_VALUE," +',
    '                    "#P2_DOWN_PAYMENT"',
    '            },',
    '            {',
    '                dataType: "json",',
    '',
    '                success: function (data) {',
    '',
    '                    if (!data.success) {',
    '                        apex.message.alert(data.message);',
    '                        return;',
    '                    }',
    '',
    '                    apex.navigation.redirect(',
    '                        data.redirect_url',
    '                    );',
    '                },',
    '',
    '                error: function (',
    '                    jqXHR,',
    '                    textStatus,',
    '                    errorThrown',
    '                ) {',
    '',
    '                    console.error(jqXHR.responseText);',
    '',
