,p_autocomplete_on_off=>'OFF'
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* =========================================================',
'   PAGE',
'   ========================================================= */',
'',
'#application-page-heading,',
'#application-overview,',
'#application-left,',
'#application-right {',
'    margin-bottom: 16px;',
'}',
'',
'#application-page-heading .t-Region-body,',
'#application-overview .t-Region-body,',
'#application-left .t-Region-body,',
'#application-right .t-Region-body,',
'#financial-summary .t-Region-body,',
'#application-details .t-Region-body,',
'#application-timeline .t-Region-body,',
'#next-steps .t-Region-body {',
'    padding: 0 !important;',
'}',
'',
'',
'/* =========================================================',
'   PAGE HEADER',
'   ========================================================= */',
'',
'.mf-page-heading {',
'    display: flex;',
'    align-items: center;',
'    justify-content: space-between;',
'    gap: 24px;',
'}',
'',
'.mf-page-heading h1 {',
'    margin: 7px 0 4px;',
'    font-size: 32px;',
'    line-height: 1.15;',
'    font-weight: 700;',
'    color: #0b1b68;',
'}',
'',
'.mf-page-heading p {',
'    margin: 0;',
'    color: #62709a;',
'    font-size: 16px;',
'}',
'',
'.mf-breadcrumb {',
'    display: flex;',
'    align-items: center;',
'    gap: 10px;',
'    font-size: 13px;',
'    color: #53618d;',
'}',
'',
'.mf-breadcrumb a {',
'    color: #53618d;',
'    text-decoration: none;',
'}',
'',
'.mf-breadcrumb a:hover {',
'    color: #1f56e5;',
'}',
'',
'.mf-breadcrumb .fa {',
'    font-size: 10px;',
'}',
'',
'.mf-back-button {',
'    border: 1px solid #d6deeb;',
'    border-radius: 7px;',
'    padding: 12px 18px;',
'    background: #fff;',
'    color: #13276b;',
'    text-decoration: none;',
'    font-weight: 500;',
'    white-space: nowrap;',
'}',
'',
'.mf-back-button .fa {',
'    margin-right: 8px;',
'}',
'',
'.mf-back-button:hover {',
'    background: #f7f9fd;',
'    text-decoration: none;',
'}',
'',
'',
'/* =========================================================',
'   APPLICATION OVERVIEW',
'   ========================================================= */',
'',
'.mf-overview-card {',
'    background: #fff;',
'    border: 1px solid #e1e6ef;',
'    border-radius: 9px;',
'    box-shadow: 0 2px 8px rgba(26, 43, 80, 0.04);',
'',
'    display: grid;',
'    grid-template-columns: 1.55fr 0.95fr 0.95fr 0.95fr 0.85fr;',
'',
'    align-items: center;',
'    min-height: 105px;',
'    padding: 18px 24px;',
'    gap: 20px;',
'}',
'',
'.mf-overview-number {',
'    display: flex;',
'    align-items: center;',
'    gap: 18px;',
'}',
'',
'.mf-overview-icon {',
'    width: 58px;',
'    height: 58px;',
'    border-radius: 50%;',
'    background: #edf4ff;',
'    color: #1559e8;',
'',
'    display: flex;',
'    align-items: center;',
'    justify-content: center;',
'',
'    font-size: 27px;',
'    flex-shrink: 0;',
'}',
'',
'.mf-overview-label {',
'    color: #65729b;',
'    font-size: 13px;',
'    margin-bottom: 5px;',
'}',
'',
'.mf-overview-id {',
'    font-size: 26px;',
'    font-weight: 700;',
'    color: #0a1b6a;',
'}',
'',
'.mf-overview-value {',
'    color: #0d1d67;',
'    font-size: 16px;',
'    font-weight: 500;',
'}',
'',
'.mf-overview-risk {',
'    border-left: 1px solid #dce3ee;',
'    padding-left: 28px;',
'}',
'',
'',
'/* =========================================================',
'   STATUS / RISK PILLS',
'   ========================================================= */',
'',
'.mf-status-pill,',
'.mf-risk-pill {',
'    display: inline-flex;',
'    align-items: center;',
'    justify-content: center;',
'',
'    border-radius: 7px;',
