'',
'    font-size: 13px;',
'    font-weight: 600;',
'}',
'',
'.mf-status-draft {',
'    background: #f1f3f5;',
'    color: #5d6470;',
'}',
'',
'.mf-status-submitted {',
'    background: #e8f0ff;',
'    color: #1d58d8;',
'}',
'',
'.mf-status-review {',
'    background: #dfeaff;',
'    color: #1358df;',
'}',
'',
'.mf-status-approved {',
'    background: #e2f7e6;',
'    color: #16802a;',
'}',
'',
'.mf-status-rejected {',
'    background: #fde8e8;',
'    color: #c52b2b;',
'}',
'',
'.mf-risk-low {',
'    background: #e3f8e5;',
'    color: #16852b;',
'}',
'',
'.mf-risk-medium {',
'    background: #fff4d5;',
'    color: #a86c00;',
'}',
'',
'.mf-risk-high {',
'    background: #fde5e5;',
'    color: #c52b2b;',
'}',
'',
'',
'/* =========================================================',
'   CARD / SECTIONS',
'   ========================================================= */',
'',
'.mf-card {',
'    background: #fff;',
'    border: 1px solid #e1e6ef;',
'    border-radius: 9px;',
'    padding: 18px;',
'    box-shadow: 0 2px 8px rgba(26, 43, 80, 0.04);',
'    margin-bottom: 16px;',
'}',
'',
'.mf-section-heading {',
'    color: #0a1b69;',
'    font-size: 18px;',
'    line-height: 1.2;',
'    font-weight: 700;',
'',
'    display: flex;',
'    align-items: center;',
'    gap: 11px;',
'',
'    margin-bottom: 16px;',
'}',
'',
'.mf-section-heading .fa {',
'    font-size: 20px;',
'}',
'',
'',
'/* =========================================================',
'   FINANCIAL SUMMARY',
'   ========================================================= */',
'',
'.mf-summary-grid {',
'    display: grid;',
