'    font-weight: 700;',
'}',
'',
'.mf-small {',
'    font-size: 14px;',
'    font-weight: 500;',
'}',
'',
'.mf-ratio-strip {',
'    display: grid;',
'    grid-template-columns: repeat(3, 1fr);',
'',
'    margin-top: 10px;',
'    padding: 14px 20px;',
'',
