'    margin: 0;',
'}',
'',
'',
'/* =========================================================',
'   RESPONSIVE',
'   ========================================================= */',
'',
'@media (max-width: 900px) {',
'',
'    .mf-page-heading {',
'        flex-direction: column;',
'        align-items: flex-start;',
'    }',
'',
'    .mf-overview-card {',
'        grid-template-columns: 1fr 1fr;',
'    }',
'',
'    .mf-overview-number {',
'        grid-column: 1 / -1;',
'    }',
'',
'    .mf-overview-risk {',
'        border-left: 0;',
'        padding-left: 0;',
'    }',
'',
'    .mf-summary-grid {',
'        grid-template-columns: 1fr 1fr;',
'    }',
'',
'    .mf-details-columns {',
'        grid-template-columns: 1fr;',
'    }',
'}',
'',
'@media (max-width: 600px) {',
'',
'    .mf-overview-card,',
'    .mf-summary-grid,',
'    .mf-ratio-strip {',
'        grid-template-columns: 1fr;',
'    }',
'',
'    .mf-ratio-strip > div {',
'        padding: 10px 0;',
'    }',
'',
'    .mf-ratio-strip > div + div {',
'        border-left: 0;',
'        border-top: 1px solid #cfe7d2;',
'    }',
'',
'    .mf-page-heading h1 {',
'        font-size: 27px;',
'    }',
'}'))
