wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1861311960781213635)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'New'
,p_static_id=>'new'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_user_id   app_users.user_id%TYPE;',
'    l_full_name app_users.full_name%TYPE;',
'    l_role      app_users.role%TYPE;',
'    l_page      NUMBER;',
'BEGIN',
'',
'    ------------------------------------------------------------',
'    -- LOAD LOGGED-IN USER',
'    ------------------------------------------------------------',
'    SELECT user_id,',
'           full_name,',
'           UPPER(TRIM(role))',
'      INTO l_user_id,',
'           l_full_name,',
'           l_role',
'      FROM app_users',
'     WHERE (',
'              LOWER(email) = LOWER(:APP_USER)',
'              OR LOWER(username) = LOWER(:APP_USER)',
'           )',
'       AND active_yn = ''Y'';',
'',
'    ------------------------------------------------------------',
'    -- SAVE USER CONTEXT IN APEX SESSION',
'    ------------------------------------------------------------',
'    :G_USER_ID   := l_user_id;',
'    :G_FULL_NAME := l_full_name;',
'    :G_USER_ROLE := l_role;',
'',
'    ------------------------------------------------------------',
'    -- DETERMINE HOME PAGE',
'    ------------------------------------------------------------',
'    CASE l_role',
'',
'        WHEN ''APPLICANT'' THEN',
'            l_page := 1;',
'',
'        WHEN ''LOAN_OFFICER'' THEN',
'            l_page := 20;',
'',
'        WHEN ''ADMIN'' THEN',
'            l_page := 40;',
'',
'        ELSE',
'            RAISE_APPLICATION_ERROR(',
'                -20001,',
'                ''Invalid application role: '' || NVL(l_role, ''(NULL)'')',
'            );',
'',
'    END CASE;',
'',
'    ------------------------------------------------------------',
'    -- REDIRECT',
'    ------------------------------------------------------------',
'    APEX_UTIL.REDIRECT_URL(',
'        APEX_PAGE.GET_URL(',
'            p_page => l_page',
'        )',
'    );',
'',
'EXCEPTION',
'',
'    WHEN NO_DATA_FOUND THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''No active APP_USERS account exists for '' || :APP_USER',
'        );',
'',
'    WHEN TOO_MANY_ROWS THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Multiple APP_USERS accounts were found for '' || :APP_USER',
'        );',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>1861311960781213635
,p_created_on=>wwv_flow_imp.dz('20261010210631Z')
,p_updated_on=>wwv_flow_imp.dz('20261010220108Z')
,p_created_by=>'RAFAELBRAYNER23@GMAIL.COM'
,p_updated_by=>'RAFAELBRAYNER23@GMAIL.COM'
);
end;
