,p_plug_template=>2103954283454391425
,p_plug_display_sequence=>60
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select',
'    ma.application_id,',
'    ma.application_number,',
'    u.full_name as applicant_name,',
'    lp.product_name,',
'    ma.loan_amount,',
'    ma.ltv,',
'    ma.dti,',
'    ma.risk_level,',
'',
'    ma.status,',
'',
'    initcap(',
'        replace(',
'            lower(ma.status),',
'            ''_'',',
'            '' ''',
'        )',
'    ) as status_display,',
'',
'    case ma.risk_level',
'        when ''HIGH''   then ''risk-high''',
'        when ''MEDIUM'' then ''risk-medium''',
'        when ''LOW''    then ''risk-low''',
'    end as risk_css,',
'',
'    case ma.status',
'        when ''UNDER_REVIEW'' then ''status-review''',
'        when ''SUBMITTED''    then ''status-submitted''',
'        when ''APPROVED''     then ''status-approved''',
'        when ''REJECTED''     then ''status-rejected''',
'        when ''DRAFT''        then ''status-draft''',
'    end as status_css,',
'',
'    ma.submitted_at,',
'',
'    case',
'        when ma.submitted_at is null then',
'            ''-''',
'',
'        when trunc(sysdate) - trunc(cast(ma.submitted_at as date)) = 0 then',
'            ''Today''',
'',
'        when trunc(sysdate) - trunc(cast(ma.submitted_at as date)) = 1 then',
'            ''1 day''',
'',
'        else',
'            (',
'                trunc(sysdate)',
'                - trunc(cast(ma.submitted_at as date))',
'            ) || '' days''',
'    end as age_display,',
'',
'    null as review_link',
'',
'from mortgage_applications ma',
'',
'join app_users u',
'    on u.user_id = ma.applicant_user_id',
'',
'join loan_products lp',
'    on lp.loan_product_id = ma.loan_product_id',
'',
'where ma.status in (',
'    ''SUBMITTED'',',
'    ''UNDER_REVIEW''',
')',
'',
'order by ma.submitted_at desc nulls last'))
