 p_id=>wwv_flow_imp.id(1973226162310976414)
,p_plug_name=>'Application History'
,p_static_id=>'application-history'
,p_title=>'<i class="fa fa-history"></i> Application History'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4075786578761660127
,p_plug_display_sequence=>190
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select',
'    al.audit_id,',
'',
'    to_char(',
'        al.created_at,',
'        ''Mon DD, YYYY HH:MI AM''',
'    ) as event_date,',
'',
'    nvl(',
'        u.full_name,',
'        ''System''',
'    ) as user_name,',
'',
'    initcap(',
'        replace(',
'            lower(al.action_type),',
'            ''_'',',
'            '' ''',
'        )',
'    ) as action_name,',
'',
'    al.description',
'',
'from audit_log al',
'',
'left join app_users u',
'    on u.user_id = al.user_id',
'',
'where al.application_id = :P22_APPLICATION_ID',
'',
'order by al.created_at desc'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
