,p_plug_display_sequence=>120
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with app_data as (',
'    select',
'        ma.application_id,',
'        ma.application_number,',
'        lp.product_name,',
'        ma.submitted_at,',
'        ma.status,',
'        ma.risk_level',
'    from mortgage_applications ma',
'    join loan_products lp',
'      on lp.loan_product_id = ma.loan_product_id',
'    where ma.application_id = :P22_APPLICATION_ID',
')',
'',
'select',
'    ''Application #'' as card_title,',
'    application_number as card_value,',
'    ''fa-file-text-o'' as icon_class,',
'    ''mf-summary-blue'' as card_class,',
'    1 as display_order',
'from app_data',
'',
'union all',
'',
'select',
'    ''Product'',',
'    product_name,',
'    ''fa-home'',',
'    ''mf-summary-orange'',',
'    2',
'from app_data',
'',
'union all',
'',
'select',
'    ''Submitted'',',
'    case',
'        when submitted_at is null then ''Not Submitted''',
'        else to_char(submitted_at, ''Mon DD, YYYY'')',
'    end,',
'    ''fa-calendar'',',
'    ''mf-summary-purple'',',
'    3',
'from app_data',
'',
'union all',
'',
'select',
'    ''Current Status'',',
'    initcap(',
'        replace(',
'            lower(status),',
'            ''_'',',
'            '' ''',
'        )',
'    ),',
'    ''fa-check-circle-o'',',
'    case status',
'        when ''APPROVED''     then ''mf-summary-green''',
'        when ''REJECTED''     then ''mf-summary-red''',
'        when ''UNDER_REVIEW'' then ''mf-summary-blue''',
'        when ''SUBMITTED''    then ''mf-summary-orange''',
'        else                     ''mf-summary-gray''',
'    end,',
'    4',
'from app_data',
'',
'union all',
'',
'select',
'    ''Risk Level'',',
'    initcap(lower(risk_level)),',
'    ''fa-line-chart'',',
'    case risk_level',
'        when ''LOW''    then ''mf-summary-green''',
'        when ''MEDIUM'' then ''mf-summary-orange''',
'        when ''HIGH''   then ''mf-summary-red''',
'        else               ''mf-summary-gray''',
'    end,',
'    5',
'from app_data',
'',
'order by display_order;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
,p_created_on=>wwv_flow_imp.dz('20261011025215Z')
,p_updated_on=>wwv_flow_imp.dz('20261011035222Z')
,p_created_by=>'RAFAELBRAYNER23@GMAIL.COM'
,p_updated_by=>'RAFAELBRAYNER23@GMAIL.COM'
);
