wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1973225805717976411)
,p_plug_name=>'Financial Analysis'
,p_static_id=>'financial-analysis'
,p_title=>'<i class="fa fa-line-chart"></i> Financial Analysis / Calculated Metrics'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2076152157930740558
,p_plug_display_sequence=>180
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with app_data as (',
'    select',
'        ltv,',
'        dti,',
'        risk_level,',
'        monthly_payment,',
'        annual_income,',
'        down_payment,',
'        property_value,',
'',
'        case',
'            when annual_income > 0 then',
'                round(',
'                    monthly_payment /',
'                    (annual_income / 12) * 100,',
'                    2',
'                )',
'        end as payment_to_income,',
'',
'        case',
'            when property_value > 0 then',
'                round(',
'                    down_payment /',
'                    property_value * 100,',
'                    2',
'                )',
'        end as down_payment_pct',
'',
'    from mortgage_applications',
'',
'    where application_id = :P22_APPLICATION_ID',
')',
'',
'',
'/* =====================================================',
'   1. LOAN TO VALUE',
'   ===================================================== */',
'',
'select',
'    ''Loan-to-Value (LTV)'' as card_title,',
'',
'    to_char(',
'        ltv,',
'        ''FM990D00''',
'    ) || ''%'' as card_value,',
'',
'    case',
'        when ltv > 90 then',
'            ''High leverage''',
'        when ltv > 80 then',
'            ''Moderate leverage''',
'        else',
'            ''Healthy leverage''',
'    end as card_description,',
'',
'    ''fa-home'' as icon_class,',
'',
'    case',
'        when ltv > 90 then ''mf-metric-red''',
'        when ltv > 80 then ''mf-metric-orange''',
'        else ''mf-metric-green''',
'    end as card_class,',
'',
'    1 as display_order',
'',
'from app_data',
'',
'',
'union all',
'',
'',
'/* =====================================================',
'   2. DEBT TO INCOME',
'   ===================================================== */',
'',
'select',
'    ''Debt-to-Income (DTI)'',',
'',
'    to_char(',
'        dti,',
'        ''FM990D00''',
'    ) || ''%'',',
'',
'    case',
'        when dti > 45 then',
'            ''High debt burden''',
'        when dti > 35 then',
'            ''Moderate debt burden''',
'        else',
'            ''Healthy debt level''',
'    end,',
'',
'    ''fa-pie-chart'',',
'',
'    case',
'        when dti > 45 then ''mf-metric-red''',
'        when dti > 35 then ''mf-metric-orange''',
'        else ''mf-metric-green''',
'    end,',
'',
'    2',
'',
'from app_data',
'',
'',
'union all',
'',
'',
'/* =====================================================',
'   3. PAYMENT TO INCOME',
'   ===================================================== */',
'',
'select',
'    ''Payment-to-Income'',',
'',
'    case',
'        when payment_to_income is null then',
'            ''N/A''',
'        else',
'            to_char(',
'                payment_to_income,',
'                ''FM990D00''',
'            ) || ''%''',
'    end,',
'',
'    case',
'        when payment_to_income is null then',
'            ''Income information unavailable''',
'',
'        when payment_to_income > 36 then',
'            ''High housing payment''',
'',
'        when payment_to_income > 28 then',
'            ''Moderate housing payment''',
'',
'        else',
'            ''Healthy housing payment''',
'    end,',
'',
'    ''fa-dollar'',',
'',
'    case',
'        when payment_to_income is null then',
'            ''mf-metric-gray''',
'',
'        when payment_to_income > 36 then',
'            ''mf-metric-red''',
'',
'        when payment_to_income > 28 then',
'            ''mf-metric-orange''',
'',
'        else',
'            ''mf-metric-green''',
'    end,',
'',
'    3',
'',
'from app_data',
'',
'',
'union all',
'',
'',
'/* =====================================================',
'   4. DOWN PAYMENT',
'   ===================================================== */',
'',
'select',
'    ''Down Payment'',',
'',
'    case',
'        when down_payment_pct is null then',
'            ''N/A''',
'        else',
'            to_char(',
'                down_payment_pct,',
'                ''FM990D00''',
'            ) || ''%''',
'    end,',
'',
'    case',
'        when down_payment_pct is null then',
'            ''Down payment unavailable''',
'',
'        when down_payment_pct < 10 then',
'            ''Low down payment''',
'',
'        when down_payment_pct < 20 then',
'            ''Moderate down payment''',
'',
'        else',
'            ''Strong down payment''',
'    end,',
'',
'    ''fa-money'',',
'',
'    case',
'        when down_payment_pct is null then',
'            ''mf-metric-gray''',
'',
'        when down_payment_pct < 10 then',
'            ''mf-metric-red''',
'',
'        when down_payment_pct < 20 then',
'            ''mf-metric-orange''',
'',
'        else',
'            ''mf-metric-green''',
'    end,',
'',
'    4',
'',
'from app_data',
'',
'',
'union all',
'',
'',
'/* =====================================================',
'   5. RISK LEVEL',
'   ===================================================== */',
'',
'select',
'    ''Risk Level'',',
'',
'    initcap(',
'        lower(risk_level)',
'    ),',
'',
'    case risk_level',
'',
'        when ''LOW'' then',
'            ''Application meets low-risk criteria''',
'',
'        when ''MEDIUM'' then',
'            ''Application requires additional review''',
'',
'        when ''HIGH'' then',
'            ''Application requires careful review''',
'',
'        else',
'            ''Risk not calculated''',
'',
'    end,',
'',
'    ''fa-line-chart'',',
'',
'    case risk_level',
'',
'        when ''LOW'' then',
'            ''mf-metric-green''',
'',
'        when ''MEDIUM'' then',
'            ''mf-metric-orange''',
'',
'        when ''HIGH'' then',
'            ''mf-metric-red''',
'',
'        else',
'            ''mf-metric-gray''',
'',
'    end,',
'',
'    5',
'',
'from app_data',
'',
'order by display_order'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
,p_created_on=>wwv_flow_imp.dz('20261011035748Z')
,p_updated_on=>wwv_flow_imp.dz('20261011213839Z')
,p_created_by=>'RAFAELBRAYNER23@GMAIL.COM'
,p_updated_by=>'RAFAELBRAYNER23@GMAIL.COM'
);
