wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1936919119966179719)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'LOAD_APPLICATION_HEADER'
,p_static_id=>'load-application-header'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'',
'    select',
'        ma.application_number,',
'        u.full_name,',
'        lp.product_name,',
'',
'        to_char(',
'            ma.submitted_at,',
'            ''Mon DD, YYYY''',
'        ),',
'',
'        ma.status,',
'        ma.risk_level,',
'',
'        case',
'            when ma.submitted_at is null then',
'                0',
'            else',
'                trunc(sysdate)',
'                - trunc(cast(ma.submitted_at as date))',
'        end',
'',
'    into',
'        :P22_APPLICATION_NUMBER,',
'        :P22_APPLICANT_NAME,',
'        :P22_PRODUCT_NAME,',
'        :P22_SUBMITTED_AT,',
'        :P22_STATUS,',
'        :P22_RISK_LEVEL,',
'        :P22_DAYS_QUEUE',
'',
'    from mortgage_applications ma',
'',
'    join app_users u',
'      on u.user_id = ma.applicant_user_id',
'',
'    join loan_products lp',
'      on lp.loan_product_id = ma.loan_product_id',
'',
'    where ma.application_id = :P22_APPLICATION_ID;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>1936919119966179719
,p_created_on=>wwv_flow_imp.dz('20261011022721Z')
,p_updated_on=>wwv_flow_imp.dz('20261011022721Z')
,p_created_by=>'RAFAELBRAYNER23@GMAIL.COM'
,p_updated_by=>'RAFAELBRAYNER23@GMAIL.COM'
);
