 p_id=>wwv_flow_imp.id(1861308841415213604)
,p_plug_name=>'Admin KPI Cards'
,p_static_id=>'mf-admin-kpi'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2076152157930740558
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select',
'    ''Total Users'' as card_title,',
'    to_char(count(*)) as card_value,',
'    ''fa-users'' as icon_class,',
'    ''mf-card-blue'' as card_class,',
'    1 as display_order',
'from app_users',
'',
'union all',
'',
'select',
'    ''Total Applications'',',
'    to_char(count(*)),',
'    ''fa-file-text-o'',',
'    ''mf-card-blue'',',
'    2',
'from mortgage_applications',
'',
'union all',
'',
'select',
'    ''Active Loan Products'',',
'    to_char(count(*)),',
'    ''fa-cube'',',
'    ''mf-card-green'',',
'    3',
'from loan_products',
'where active_yn = ''Y''',
'',
'union all',
'',
'select',
'    ''Active Interest Rates'',',
'    to_char(count(*)),',
'    ''fa-percent'',',
'    ''mf-card-orange'',',
'    4',
'from interest_rates',
'where active_yn = ''Y''',
'  and effective_from <= trunc(sysdate)',
'  and (',
'        effective_to is null',
'        or effective_to >= trunc(sysdate)',
'      )',
'',
'union all',
'',
'select',
'    ''Errors Today'',',
'    to_char(count(*)),',
'    ''fa-exclamation-triangle'',',
'    ''mf-card-red'',',
'    5',
'from app_error_log',
'where created_at >= cast(trunc(sysdate) as timestamp)',
'  and created_at < cast(trunc(sysdate) + 1 as timestamp)',
'',
'union all',
'',
'select',
'    ''Audit Events Today'',',
'    to_char(count(*)),',
'    ''fa-file-text-o'',',
'    ''mf-card-purple'',',
'    6',
'from audit_log',
'where created_at >= cast(trunc(sysdate) as timestamp)',
'  and created_at < cast(trunc(sysdate) + 1 as timestamp)',
'',
'order by display_order'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
